package com.vms.vendorcontractmanagement.service; import com.vms.vendorcontractmanagement.dto.DepartmentDtos.*; import com.vms.vendorcontractmanagement.dto.VendorDtos; import com.vms.vendorcontractmanagement.entity.*; import com.vms.vendorcontractmanagement.exception.*; import com.vms.vendorcontractmanagement.repository.*; import lombok.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.util.*;
@Service @RequiredArgsConstructor public class DepartmentService {final DepartmentRepository departments;final VendorRepository vendors;final VendorService vendorService; public List<Response> list(){return departments.findAll().stream().map(this::dto).toList();} public Response get(Long id){return dto(find(id));} @Transactional public Response create(Request r){Department d=new Department();d.setDepartmentName(r.departmentName());d.setManagerName(r.managerName());return dto(departments.save(d));} @Transactional public Response update(Long id,Request r){Department d=find(id);d.setDepartmentName(r.departmentName());d.setManagerName(r.managerName());return dto(d);} @Transactional public void delete(Long id){Department d=find(id); for(Vendor vendor:new HashSet<>(d.getVendors())) vendor.getDepartments().remove(d); departments.delete(d);} public List<VendorDtos.Response> vendorList(Long id){return find(id).getVendors().stream().map(vendorService::dto).toList();} @Transactional public void assign(Long id,Long vendorId){Department d=find(id);Vendor v=vendorService.find(vendorId);v.getDepartments().add(d);} @Transactional public void remove(Long id,Long vendorId){Department d=find(id);Vendor v=vendorService.find(vendorId);v.getDepartments().remove(d);} Department find(Long id){return departments.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Department not found"));} Response dto(Department d){return new Response(d.getId(),d.getDepartmentName(),d.getManagerName());} }
